    SELECT channel_id, COUNT(DISTINCT customer_id) AS buyers
    FROM dw.fact_order
    WHERE pay_status = ''已支付''
      AND order_date BETWEEN ''2026-06-01'' AND ''2026-06-20''
    GROUP BY channel_id
),
traffic AS (
    SELECT channel_id, SUM(visitors) AS uv
    FROM dw.fact_traffic_daily
    WHERE date BETWEEN ''2026-06-01'' AND ''2026-06-20''
    GROUP BY channel_id
)
SELECT ch.channel_name,
       ROUND(p.buyers * 100.0 / NULLIF(t.uv, 0), 1) AS conversion_rate
FROM payers p
JOIN traffic t ON p.channel_id = t.channel_id
JOIN dw.dim_channel ch ON p.channel_id = ch.channel_id
